-- Nomenclature nationale des produits pharmaceutiques (MIPH), version au 31 août 2026
-- Supabase: SQL Editor > New query > paste everything > Run
-- Safe to re-run: it reloads the table from scratch.

create extension if not exists pg_trgm;

create table if not exists nomenclature (
  id bigint generated always as identity primary key,
  statut text not null check (statut in ('enregistre','non_renouvele','retire')),
  n_enregistrement text not null,
  code text,                         -- same CODE as observatoire_officine
  dci_brut text not null,
  nom_marque text not null,
  forme text,
  dosage text,
  dosage_converti boolean not null default false,  -- Excel stored a number, converted (e.g. 0.05 -> 5%): check
  conditionnement text,
  liste text,                        -- LISTE I / LISTE II / STUPEFIANT / null
  hopital boolean not null default false,   -- P1 HOP
  officine boolean not null default false,  -- P2 OFF
  obs text,
  laboratoire text,
  pays text,
  date_enregistrement_initial date,
  date_enregistrement_final date,
  type text,                         -- GE generique / RE reference / BIO biosimilaire
  fabrique_local boolean,            -- STATUT F = true, I (importe) = false
  duree_stabilite text,
  date_retrait date,                 -- retraits only, when a real date was given
  retrait_info text,                 -- raw text when not a date (RETRAIT, ABROGATION...)
  motif_retrait text,
  version text not null default '2026-08-31',
  importe_le timestamptz not null default now()
);

create index if not exists nom_code_idx on nomenclature (code);
create index if not exists nom_statut_idx on nomenclature (statut);
create index if not exists nom_reg_idx on nomenclature (n_enregistrement);
create index if not exists nom_marque_trgm on nomenclature using gin (nom_marque gin_trgm_ops);
create index if not exists nom_dci_trgm on nomenclature using gin (dci_brut gin_trgm_ops);

alter table nomenclature enable row level security;
drop policy if exists "lecture publique" on nomenclature;
create policy "lecture publique" on nomenclature for select using (true);

truncate nomenclature;

-- What a GP can prescribe in town: registered + available in officine, with lab and origin.
-- dans_observatoire = also on the ministry observatory list (2022) you loaded before.
create or replace view medicaments_officine as
select n.*,
  exists (
    select 1 from observatoire_officine o
    where o.code = n.code and upper(trim(o.nom_marque)) = upper(trim(n.nom_marque))
  ) as dans_observatoire
from nomenclature n
where n.statut = 'enregistre' and n.officine;

select statut, count(*) from nomenclature group by statut order by statut;
-- expected: enregistre 5425, non_renouvele 1491, retire 2679
